#include <matlog/docs/examples.h>

static const char text_algebra_quadratic [] =
	"# A quadratic equation\n"
	"# Solve x^2 - 5x + 6 = 0 and check the answer, then look at one with n"
	"o real roots.\n"
	"# The roots of f(x) = x^2 - 5x + 6:\n"
	"m:algebra f(x) = x^2 - 5x + 6\n"
	"m:algebra solve(f(x), x)\n"
	"# Check: f is zero at both roots.\n"
	"m:algebra f(2)\n"
	"m:algebra f(3)\n"
	"# The factored form is the same polynomial.\n"
	"m:algebra expand((x - 2)*(x - 3))\n"
	"# The discriminant b^2 - 4ac tells how many real roots there are. For "
	"x^2 + x + 1:\n"
	"m:algebra 1^2 - 4*1*1\n"
	"# It is negative, so there is no real root and solve gives the empty s"
	"et.\n"
	"m:algebra solve(x^2 + x + 1, x)\n";

static const char text_basics_exact_numbers [] =
	"# Exact numbers\n"
	"# Fractions stay fractions; only a root or a trig function makes an ap"
	"proximation.\n"
	"# matlog computes with exact fractions, so there is no rounding error "
	"to hunt for.\n"
	"m:algebra 1/3 + 1/6\n"
	"m:algebra 0.1 + 0.2\n"
	"m:algebra 2^100\n"
	"m:algebra 30!\n"
	"# A root of a perfect square stays exact, any other root is an approxi"
	"mation (the sign says so).\n"
	"m:algebra sqrt(16/25)\n"
	"m:algebra sqrt(2)\n"
	"# Dividing integers is exact too.\n"
	"m:algebra gcd(84, 36)\n"
	"m:algebra lcm(4, 6)\n"
	"m:algebra 22/7 - pi\n"
	"# Press F3 on a line to see the steps, if it has some.\n";

static const char text_calculus_newton_sqrt2 [] =
	"# Newton's method for the square root of 2\n"
	"# Each step doubles the number of correct digits, and with exact fract"
	"ions you see them.\n"
	"# To solve x^2 = 2 look for the zero of f(x) = x^2 - 2. Newton's step "
	"is x - f(x)/f'(x):\n"
	"m:algebra g(x) = x - (x^2 - 2)/(2x)\n"
	"# Start at 1 and repeat the step. The numbers are exact fractions:\n"
	"m:algebra x1 = g(1)\n"
	"m:algebra x2 = g(x1)\n"
	"m:algebra x3 = g(x2)\n"
	"m:algebra x4 = g(x3)\n"
	"# The error of each guess, x^2 - 2, shrinks very fast:\n"
	"m:algebra x1^2 - 2\n"
	"m:algebra x2^2 - 2\n"
	"m:algebra x3^2 - 2\n"
	"m:algebra x4^2 - 2\n"
	"# Compare with the library root:\n"
	"m:algebra sqrt(2)\n";

static const char text_calculus_tangent_line [] =
	"# The tangent line\n"
	"# Differentiate, and use the derivative to find the tangent line of a "
	"curve at a point.\n"
	"# The curve y = x^3 - 2x and its derivative:\n"
	"m:algebra f(x) = x^3 - 2x\n"
	"m:algebra fp = diff(f(x), x)\n"
	"# The point is x = 1: the value and the slope there.\n"
	"m:algebra y0 = f(1)\n"
	"m:algebra k = subs(fp, x, 1)\n"
	"# The tangent line is y = y0 + k (x - 1):\n"
	"m:algebra expand(y0 + k*(x - 1))\n"
	"# The area under the curve between 1 and 2:\n"
	"m:algebra integrate(f(x), x, 1, 2)\n";

static const char text_lambda_church_arithmetic [] =
	"# Arithmetic with nothing but functions\n"
	"# In the lambda calculus a number is a function that applies f n times"
	". Everything else is built from that.\n"
	"# The successor, addition and multiplication of Church numerals:\n"
	"m:lambda succ = \316\273n f x. f (n f x)\n"
	"m:lambda plus = \316\273m n f x. m f (n f x)\n"
	"m:lambda mult = \316\273m n f. m (n f)\n"
	"# Two is a function that applies f twice. Add one:\n"
	"m:lambda succ 2\n"
	"# 2 + 3 is the numeral 5 (apply f five times):\n"
	"m:lambda plus 2 3\n"
	"# 3 * 4 is the numeral 12:\n"
	"m:lambda mult 3 4\n"
	"# Booleans are functions that choose:\n"
	"m:lambda true = \316\273a b. a\n"
	"m:lambda false = \316\273a b. b\n"
	"m:lambda and = \316\273p q. p q p\n"
	"m:lambda and true false\n"
	"# F3 on a line shows every beta step of the reduction:\n"
	"m:lambda mult 2 2\n";

static const char text_linalg_least_squares [] =
	"# A least squares line\n"
	"# Fit y = a + b t to four measurements with the normal equations.\n"
	"# Measurements: the times t and the values y.\n"
	"m:algebra X = [[1, 0], [1, 1], [1, 2], [1, 3]]\n"
	"m:algebra y = [1, 3, 4, 8]\n"
	"# The line a + b t that is closest to the points solves  X^T X c = X^T"
	" y:\n"
	"m:algebra N = transpose(X)*X\n"
	"m:algebra r = transpose(X)*y\n"
	"m:algebra c = solve(N, r)\n"
	"# The first entry is a = 7/10 and the second is b = 11/5: the line is "
	"y = 7/10 + 11/5 t.\n"
	"# The fitted values and the residuals (the error that is left):\n"
	"m:algebra X*c\n"
	"m:algebra y - X*c\n"
	"# The residuals are perpendicular to the columns of X, so X^T times th"
	"em is zero:\n"
	"m:algebra transpose(X)*(y - X*c)\n";

static const char text_linalg_linear_system [] =
	"# A linear system\n"
	"# Solve three equations in three unknowns with a matrix, and check the"
	" answer.\n"
	"# 2x + y - z = 8,  -3x - y + 2z = -11,  -2x + y + 2z = -3\n"
	"m:algebra A = [[2, 1, -1], [-3, -1, 2], [-2, 1, 2]]\n"
	"m:algebra b = [8, -11, -3]\n"
	"# The system has one solution when the determinant is not zero:\n"
	"m:algebra det(A)\n"
	"m:algebra x = solve(A, b)\n"
	"# Check that A x is b:\n"
	"m:algebra A*x\n"
	"# The same with the inverse (F3 on this line shows the row reduction):\n"
	"m:algebra inv(A)*b\n"
	"m:algebra rank(A)\n"
	"# The reduced row echelon form of A with b beside it is where the answ"
	"er is read off:\n"
	"m:algebra rref([[2, 1, -1, 8], [-3, -1, 2, -11], [-2, 1, 2, -3]])\n";

static const char text_linalg_rotations [] =
	"# Rotations as matrices\n"
	"# A rotation matrix turns a vector and keeps its length. With cos = 3/"
	"5 and sin = 4/5 everything is exact.\n"
	"m:algebra R = [[3/5, -4/5], [4/5, 3/5]]\n"
	"m:algebra v = [1, 0]\n"
	"# Rotate the vector:\n"
	"m:algebra R*v\n"
	"# Its length is the same:\n"
	"m:algebra norm(R*v)\n"
	"# A rotation is orthogonal: the transpose is the inverse, and the dete"
	"rminant is 1.\n"
	"m:algebra transpose(R)*R\n"
	"m:algebra det(R)\n"
	"# Two rotations in a row are one rotation by the sum of the angles:\n"
	"m:algebra R*R\n"
	"# Rotating back with the transpose gives the vector again:\n"
	"m:algebra transpose(R)*(R*v)\n";

static const char text_logic_minimise_circuit [] =
	"# Simplifying a logic circuit\n"
	"# A circuit is a boolean expression. matlog finds the smallest sum of "
	"products and a truth table checks it.\n"
	"m:boolean f = (a & b) | (a & ~b) | (~a & b)\n"
	"# The expression is the same as a OR b. The result above is the minima"
	"l form.\n"
	"m:boolean table a | b\n"
	"# De Morgan: not (a and b) is (not a) or (not b). Two expressions are "
	"equal when == gives true:\n"
	"m:boolean ~(a & b) == (~a | ~b)\n"
	"# Exclusive or built from and, or and not, and its truth table:\n"
	"m:boolean table (a | b) & ~(a & b)\n"
	"# A circuit with a redundant gate: the term (a & b) is covered by a.\n"
	"m:boolean a | (a & b)\n"
	"# A tautology and a contradiction:\n"
	"m:boolean a | ~a\n"
	"m:boolean a & ~a\n";

static const char text_robotics_two_link_arm [] =
	"# A robot arm with two links\n"
	"# Forward and inverse kinematics of a planar arm. With rational sines "
	"and cosines the whole computation is exact.\n"
	"# A joint is a rotation by an angle, given by its cosine and sine:\n"
	"m:algebra rot(c, s) = [[c, -s], [s, c]]\n"
	"# Two links of length 5. The first joint turns by (3/5, 4/5), the seco"
	"nd by (3/5, 4/5) more:\n"
	"m:algebra l1 = 5\n"
	"m:algebra l2 = 5\n"
	"m:algebra R1 = rot(3/5, 4/5)\n"
	"m:algebra R2 = rot(3/5, 4/5)\n"
	"# Forward kinematics: the hand is link 1 turned by R1, plus link 2 tur"
	"ned by R1 R2.\n"
	"m:algebra p = R1*[l1, 0] + R1*R2*[l2, 0]\n"
	"# Inverse kinematics: given only the hand position p, find the joint a"
	"ngles.\n"
	"# The law of cosines gives the second joint from the distance to the h"
	"and:\n"
	"m:algebra c2 = (dot(p, p) - l1^2 - l2^2)/(2*l1*l2)\n"
	"m:algebra s2 = sqrt(1 - c2^2)\n"
	"# (The other sign of s2 is the elbow bent the other way.) The first li"
	"nk plus the turned second link is a vector w = (l1 + l2 c2, l2 s2) tha"
	"t R1 turns into p:\n"
	"m:algebra w = [l1 + l2*c2, l2*s2]\n"
	"# R1 = [[c1, -s1], [s1, c1]] solves  [[wx, -wy], [wy, wx]] [c1, s1] = "
	"p\n"
	"m:algebra cs1 = solve([[l1 + l2*c2, -l2*s2], [l2*s2, l1 + l2*c2]], p)\n"
	"# The answer (c1, s1) = (3/5, 4/5) is the first joint we started with."
	" Check the forward kinematics:\n"
	"m:algebra rot(3/5, 4/5)*[l1, 0] + rot(3/5, 4/5)*rot(c2, s2)*[l2, 0]\n"
	"# With angles instead of cosines and sines the same formulas use acos "
	"and atan:\n"
	"m:algebra q2 = acos(3/5)\n"
	"m:algebra q1 = atan(44/8) - atan(5*sin(q2)/(5 + 5*cos(q2)))\n";

static const char text_units_kinetic_energy [] =
	"# Units in a physics problem\n"
	"# A car of 1200 kg drives at 90 km/h. How much energy does it have, an"
	"d how far does it travel in 20 s?\n"
	"# The mass and the speed, with their units:\n"
	"m:algebra mass = 1200 kg\n"
	"m:algebra v = 90 km/h\n"
	"# Convert the speed to SI units:\n"
	"m:algebra v to m/s\n"
	"# The kinetic energy is mass v^2 / 2. The units multiply out by themse"
	"lves:\n"
	"m:algebra mass*(v to m/s)^2/2\n"
	"# In kilojoules:\n"
	"m:algebra mass*(v to m/s)^2/2 to kJ\n"
	"# The distance in 20 seconds:\n"
	"m:algebra (v to m/s)*20 s\n"
	"# Lengths in different units add up (the sum is in metres), and to con"
	"verts back:\n"
	"m:algebra 5 km + 300 m\n"
	"m:algebra 5300 m to km\n"
	"# Time to stop with a deceleration of 8 m/s^2 from this speed:\n"
	"m:algebra (v to m/s)/(8 m/s^2)\n";

